let menuIcon=document.querySelector(".menu-icon"),mobileMenu=document.querySelector(".menu-mobile");try{menuIcon.addEventListener("click",()=>{console.log("Icon clicked!"),mobileMenu.classList.contains("display")?(menuIcon.classList.remove("display"),mobileMenu.classList.remove("display")):(menuIcon.classList.add("display"),mobileMenu.classList.add("display"))})}catch(e){console.log("No menu Icon")}for(var dropdowns=document.getElementsByClassName("subdrop"),i=0;i<dropdowns.length;i++)console.log(i),dropdowns[i].addEventListener("click",function(){console.log("Dropdown clicked!"),this.classList.contains("active")?this.classList.remove("active"):this.classList.add("active")});